"use client";

import { PARTNER_LOGO_CAROUSEL_ROWS } from "@/lib/partner-logos";
import { LogoCarouselSwapper } from "@/components/sora-ui/effects/logo-carousel-swapper";

export function LogoCarouselSwapperExample() {
  return (
    <div className="flex min-h-40 w-full items-center justify-center px-4 py-10">
      <LogoCarouselSwapper
        aria-label="Partner logos"
        className="max-w-3xl"
        interval={3000}
        rows={PARTNER_LOGO_CAROUSEL_ROWS}
        stagger={0.12}
      />
    </div>
  );
}
